<?php
declare(strict_types=1);require_once __DIR__.'/includes/api.php';require_once __DIR__.'/includes/registration_schema.php';$admin=require_admin_json();ensure_registration_schema();$action=$_GET['action']??(($_SERVER['REQUEST_METHOD']??'GET')==='GET'?'list':'save');function reg_pdf(string $key):?array{$f=$_FILES[$key]??null;if(!$f||($f['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return null;if(($f['error']??1)!==UPLOAD_ERR_OK||($f['size']??0)>30*1024*1024)send_json(['ok'=>false,'message'=>'PDF แต่ละไฟล์ต้องไม่เกิน 30MB'],422);$tmp=(string)$f['tmp_name'];if((string)mime_content_type($tmp)!=='application/pdf')send_json(['ok'=>false,'message'=>'รองรับเฉพาะ PDF'],422);$dir=__DIR__.'/uploads/registration';if(!is_dir($dir))mkdir($dir,0775,true);$name=date('YmdHis').'-'.$key.'-'.bin2hex(random_bytes(6)).'.pdf';if(!move_uploaded_file($tmp,$dir.'/'.$name))send_json(['ok'=>false,'message'=>'บันทึก PDF ไม่สำเร็จ'],500);return['url'=>'uploads/registration/'.$name,'name'=>basename((string)$f['name'])];}
try{if($action==='list'){$rows=db()->query('SELECT * FROM registration_plans ORDER BY updated_at DESC,id DESC')->fetchAll();send_json(['ok'=>true,'plans'=>array_map(fn($r)=>['id'=>(string)$r['id'],'title'=>$r['title'],'description'=>$r['description']??'','status'=>$r['status'],'files'=>['primary'=>['url'=>$r['primary_pdf']??'','name'=>$r['primary_name']??''],'lower'=>['url'=>$r['lower_pdf']??'','name'=>$r['lower_name']??''],'upper'=>['url'=>$r['upper_pdf']??'','name'=>$r['upper_name']??'']]],$rows)]);} $d=request_data();$id=(int)($d['id']??0);if($action==='delete'){$ns=db()->prepare('SELECT title FROM registration_plans WHERE id=:id');$ns->execute(['id'=>$id]);$target=(string)($ns->fetchColumn()?:'แผนการลงทะเบียน');db()->prepare('DELETE FROM registration_plans WHERE id=:id')->execute(['id'=>$id]);write_admin_log((int)$admin['id'],'delete_registration','registration_plan',(string)$id,$target,'ลบแผนการลงทะเบียน '.$target);send_json(['ok'=>true,'message'=>'ลบแผนการลงทะเบียนแล้ว']);}$title=text_value($d,'title');$description=nullable_text($d,'description');$status=text_value($d,'status')==='draft'?'draft':'published';if($title==='')send_json(['ok'=>false,'message'=>'กรุณาระบุชื่อแผน'],422);$uploads=['primary'=>reg_pdf('primaryPdf'),'lower'=>reg_pdf('lowerPdf'),'upper'=>reg_pdf('upperPdf')];if($id){$s=db()->prepare('SELECT * FROM registration_plans WHERE id=:id');$s->execute(['id'=>$id]);$old=$s->fetch();if(!$old)send_json(['ok'=>false,'message'=>'ไม่พบข้อมูล'],404);foreach(['primary','lower','upper']as$l){$uploads[$l]=$uploads[$l]?:['url'=>$old[$l.'_pdf'],'name'=>$old[$l.'_name']];}$s=db()->prepare('UPDATE registration_plans SET title=:title,description=:description,primary_pdf=:pp,primary_name=:pn,lower_pdf=:lp,lower_name=:ln,upper_pdf=:up,upper_name=:un,status=:status,updated_by=:admin WHERE id=:id');$s->execute(['title'=>$title,'description'=>$description,'pp'=>$uploads['primary']['url'],'pn'=>$uploads['primary']['name'],'lp'=>$uploads['lower']['url'],'ln'=>$uploads['lower']['name'],'up'=>$uploads['upper']['url'],'un'=>$uploads['upper']['name'],'status'=>$status,'admin'=>$admin['id'],'id'=>$id]);write_admin_log((int)$admin['id'],'update_registration','registration_plan',(string)$id,$title,'แก้ไขแผนการลงทะเบียน '.$title);send_json(['ok'=>true,'message'=>'แก้ไขแผนการลงทะเบียนแล้ว']);}foreach($uploads as$x)if(!$x)send_json(['ok'=>false,'message'=>'รายการใหม่ต้องมี PDF ครบทั้ง 3 ระดับ'],422);$s=db()->prepare('INSERT INTO registration_plans(title,description,primary_pdf,primary_name,lower_pdf,lower_name,upper_pdf,upper_name,status,created_by,updated_by)VALUES(:title,:description,:pp,:pn,:lp,:ln,:up,:un,:status,:created,:updated)');$s->execute(['title'=>$title,'description'=>$description,'pp'=>$uploads['primary']['url'],'pn'=>$uploads['primary']['name'],'lp'=>$uploads['lower']['url'],'ln'=>$uploads['lower']['name'],'up'=>$uploads['upper']['url'],'un'=>$uploads['upper']['name'],'status'=>$status,'created'=>$admin['id'],'updated'=>$admin['id']]);$newId=(string)db()->lastInsertId();write_admin_log((int)$admin['id'],'create_registration','registration_plan',$newId,$title,'เพิ่มแผนการลงทะเบียน '.$title);send_json(['ok'=>true,'message'=>'เพิ่มแผนการลงทะเบียนแล้ว']);}catch(Throwable $e){error_log('Registration API: '.$e->getMessage());send_json(['ok'=>false,'message'=>'บันทึกแผนการลงทะเบียนไม่สำเร็จ'],500);}
